<script setup lang="ts">
import { computed, ref, useId } from 'vue'
const id=useId()
const value=ref(62)
const mode=ref('arc')
const available=ref(true)
const level=computed(()=>value.value<60?'Low sample load':value.value<85?'Elevated sample load':'High sample load')
const angle=computed(()=>-90+value.value*1.8)
const point=computed(()=>{const a=angle.value*Math.PI/180;return {x:100+66*Math.sin(a),y:100-66*Math.cos(a)}})
function reset(){value.value=62;mode.value='arc';available.value=true}
</script>
<template>
<section class="meters-demo" aria-label="Bounded measurement example"><p>Fictitious load on a fixed 0–100 scale, not task completion or live telemetry.</p><div class="meters-controls"><label :for="id+'-value'">Sample load: {{ value }}%<input :id="id+'-value'" v-model.number="value" type="range" min="0" max="100" step="1" :disabled="!available"></label><label>Dial style<select v-model="mode"><option value="arc">Arc</option><option value="needle">Needle</option><option value="both">Arc and needle</option></select></label><label class="meter-check"><input v-model="available" type="checkbox">Measurement available</label><button type="button" @click="reset">Reset example</button></div><div v-if="available" class="meters-display"><div class="meters-dial"><svg viewBox="0 0 200 140" aria-hidden="true"><path d="M20 100 A80 80 0 0 1 180 100" class="dial-track"/><path v-if="mode!=='needle'" d="M20 100 A80 80 0 0 1 180 100" pathLength="100" class="dial-fill" :stroke-dasharray="value+' 100'"/><line v-if="mode!=='arc'" x1="100" y1="100" :x2="point.x" :y2="point.y" class="dial-needle"/><circle v-if="mode!=='arc'" cx="100" cy="100" r="5" class="dial-center"/><text x="18" y="128">0</text><text x="164" y="128">100</text></svg><strong>{{ value }}%</strong><p>{{ level }}</p></div><div class="meters-native"><label :for="id+'-meter'">Equivalent native meter</label><meter :id="id+'-meter'" :value="value" min="0" max="100" low="60" high="85" optimum="0">{{ value }}%</meter><p>Low &lt;60, elevated 60–84, high ≥85. Sample thresholds only.</p></div></div><p v-else class="meter-unavailable">Measurement unavailable. No dial or meter value is presented; this is not a measured zero.</p><p role="status">{{ available?'Sample load '+value+'%. '+level+'.':'Sample measurement unavailable.' }}</p></section>
</template>
<style scoped>
.meters-demo{border:1px solid var(--vp-c-divider);border-radius:14px;padding:18px;margin:20px 0}.meters-controls{display:flex;gap:14px;align-items:end;flex-wrap:wrap}.meters-controls label{display:grid;gap:6px;font-size:13px;font-weight:650;max-width:100%;min-width:0}.meters-controls .meter-check{display:flex;align-items:center}.meters-controls input[type=range]{width:180px;max-width:100%;accent-color:var(--vp-c-brand-1)}.meters-controls select{appearance:auto;padding:8px;border:1px solid var(--vp-c-divider);border-radius:8px;background:var(--vp-c-bg);color:var(--vp-c-text-1)}.meters-demo button{padding:8px 10px;border:1px solid var(--vp-c-divider);border-radius:8px;background:var(--vp-c-bg-soft)}.meters-demo :is(input,select,button):focus-visible{outline:2px solid var(--vp-c-brand-1);outline-offset:3px}.meters-display{display:grid;grid-template-columns:1fr 1fr;gap:20px;align-items:center;padding:20px 0}.meters-dial{max-width:240px;margin:auto;text-align:center}.meters-dial svg{display:block;width:100%;height:auto;overflow:visible}.meters-dial path{fill:none;stroke-width:12}.dial-track{stroke:var(--vp-c-divider)}.dial-fill{stroke:var(--vp-c-brand-1);transition:stroke-dasharray .2s ease-out}.dial-needle{stroke:var(--vp-c-text-1);stroke-width:3;transition:x2 .2s ease-out,y2 .2s ease-out}.dial-center{fill:var(--vp-c-text-1)}.meters-dial text{fill:var(--vp-c-text-2);font-size:12px}.meters-dial strong{font-size:28px;font-variant-numeric:tabular-nums}.meters-dial p,.meters-native p{font-size:13px}.meters-native meter{display:block;width:100%;height:22px;margin-top:10px}.meter-unavailable{padding:16px;background:var(--vp-c-bg-soft);border-radius:10px}@media(max-width:700px){.meters-display{grid-template-columns:1fr}}@media(prefers-reduced-motion:reduce){.dial-fill,.dial-needle{transition:none}}
</style>
